@kt.kernel
def k(x=kt.In("R", 32), y=kt.Out("R", 32), *, scale=2.0, rows=kt.auto(8, 4)):
    kt.require(x.shape[0] % (2 * rows) == 0, "rows")
    for c in kt.par(2, on=kt.vc):
        for t in kt.range(x.shape[0] // 2 // rows):
            r = c * (x.shape[0] // 2) + t * rows
            v = kt.unpack(kt.load(x[r : r + rows, :]))
            kt.store(y[r : r + rows, :], v * scale)

def facts():
    t = k.trace({"x": TY.TensorSpec.make((16, 32))}, machine=MACHINE)
    return {
        "type": type(t).__name__,
        "name": t.name,
        "head": t.text.split("\n")[2],
        "params": [[n, type(s).__name__] for n, s in t.params],
        "roles": t.roles,
        "consts": t.consts,
        "machine": [t.machine.mg, t.machine.vc, t.machine.nodes],
        "source": t.source.splitlines()[0],
    }
